import { User } from './user.entity';

describe('UserService', () => {
 let service: UserService;

 beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [UserService],
    }).compile();

    service = module.get<UserService>(UserService);
  });

 describe('create', () => {
    it('should create a new user', async () => {
      const userData = {
        email: 'test@example.com',
        password: 'password',
        confirmPassword: 'password',
      };

      const createdUser = await service.create(userData);

      expect(createdUser.email).toBe('test@example.com');
      expect(createdUser.password).toBe('password');
      expect(createdUser.confirmPassword).toBeUndefined();
    });
  });

 describe('findOne', () => {
    it('should find a user by email', async () => {
      const user = new User();
      user.email = 'test@example.com';
      user.password = 'password';

      const foundUser = await service.findOne(user.email);

      expect(foundUser.email).toBe('test@example.com');
      expect(foundUser.password).toBe('password');
    });
  });

 describe('update', () => {
    it('should update a user', async () => {
      const user = new User();
      user.email = 'test@example.com';
      user.password = 'password';

      const updatedUserData = {
        email: 'updated@example.com',
        password: 'updatedPassword',
      };

      const updatedUser = await service.update(user.email, updatedUserData);

      expect(updatedUser.email).toBe('updated@example.com');
      expect(updatedUser.password).toBe('updatedPassword');
    });
  });

 describe('delete', () => {
    it('should delete a user', async () => {
      const user = new User();
      user.email = 'test@example.com';
      user.password = 'password';

      await service.create(user);
      const deletedUser = await service.delete(user.email);

      expect(deletedUser).toBeTruthy();
    });
  });
});
