];
```

**src/Database.php**

```php
<?php
class Database
{
    private $pdo;

    public function __construct(array $config)
    {
        $this->pdo = new PDO(
            "mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",
            $config['username'],
            $config['password'],
            [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            ]
        );
    }

    public function saveMessage(string $messageBody)
    {
        $sql = "INSERT INTO messages (body) VALUES (?)";
        $stmt = $this->pdo->prepare($sql);
        $stmt->execute([$messageBody]);
    }
}
```

**src/SqsClient.php**

```php
<?php
use Aws\Sqs\SqsClient;
use Aws\Exception\AwsException;

class SqsClient
{
    private $sqs;

    public function __construct(array $config)
    {
        $this->sqs = new SqsClient([
            'region' => $config['region'],
            'version' => 'latest',
            'credentials' => [
                'key' => $config['aws_access_key_id'],
                'secret' => $config['aws_secret_access_key'],
            ],
        ]);
    }

    public function receiveMessages(int $maxNumberOfMessages = 10)
    {
        try {
            $result = $this->sqs->receiveMessage([
                'QueueUrl' => $this->sqs->getQueueUrl(['QueueName' => 'your_queue_name'])->get('QueueUrl'),
                'MaxNumberOfMessages' => $maxNumberOfMessages,
            ]);

            return $result->get('Messages');
        } catch (AwsException $e) {
            // Output error message if fails
            error_log($e->getMessage());
            return [];
        }
    }

    public function deleteMessage(string $receiptHandle)
    {
        $this->sqs->deleteMessage([
            'QueueUrl' => $this->sqs->getQueueUrl(['QueueName' => 'your_queue_name'])->get('QueueUrl'),
            'ReceiptHandle' => $receiptHandle,
        ]);
    }
}
```

**src/MessageProcessor.php**

```php
<?php
class MessageProcessor
{
    private $sqsClient;
    private $database;

    public function __construct(SqsClient $sqsClient, Database $database)
    {
        $this->sqsClient = $sqsClient;
        $this->database = $database;
    }

    public function processMessages()
    {
        $messages = $this->sqsClient->receiveMessages();

        foreach ($messages as $message) {
            $this->database->saveMessage($message['Body']);
            $this->sqsClient->deleteMessage($message['ReceiptHandle']);
        }
    }
}
```

**index.php**

```php
<?php
require 'vendor/autoload.php';

use Dotenv\Dotenv;

$dotenv = new Dotenv(__DIR__);
$dotenv->load();

$databaseConfig = require 'config/database.php';
$awsConfig = require 'config/aws.php';

$database = new Database($databaseConfig);
$sqsClient = new SqsClient($awsConfig);
$messageProcessor = new MessageProcessor($sqsClient, $database);

$messageProcessor->processMessages();
```

To run the application, install dependencies using Composer, set up your AWS credentials and MySQL database, and then execute `index.php`. The application will continuously process messages from the SQS queue and store them in the MySQL database.
