import React from 'react';

function VisuallyHidden({ text, as = 'span', noTranslate = false, additionalAttributes = {} }: {
  text: string;
  as?: string;
  noTranslate?: boolean;
  additionalAttributes?: Record<string, any>;
}) {
  const attributes = {
    ...additionalAttributes,
    style: {
      position: 'absolute',
      width: '1px',
      height: '1px',
      padding: '0',
      margin: '0',
      overflow: 'hidden',
      clip: 'rect(0, 0, 0, 0)',
      border: '0',
    },
  };

