import React from 'react';

function VisuallyHidden({
 text,
 as: Tag = 'span',
 noTranslate = false,
 additionalAttributes = {},
}) {
 const attributes = {
    'aria-hidden': 'true',
    ...(noTranslate && { 'data-notranslate': 'true' }),
    ...additionalAttributes,
  };

  return (
    <Tag {...attributes}>
      {text}
      <style jsx>{`
        {
          border: 0;
          clip: rect(0 0 0 0);
          height: 1px;
          margin: -1px;
          overflow: hidden;
          padding: 0;
          position: absolute;
          white-space: nowrap;
          width: 1px;
        }
      `}</style>
    </Tag>
  );
}

export default VisuallyHidden;
