            for (float angle = centerAngle - fov / 2; angle &lt; centerAngle + fov / 2; angle += Quality(fov, quality, screenWidth))
            {
                float endX = (float)(startX + Math.Cos(angle) * 1000);
                float endY = (float)(startY + Math.Sin(angle) * 1000);

                section = FacingSection(angle);

                if (section == "NE")
                {
                    for (float i = startX; i &lt; endX; i += quality)
                    {
