        public static string FacingSection(float angle)
        {
            string facing = "";
            if (angle &gt;= 0 &amp;&amp; angle &lt; Math.PI / 2)
            {
                facing = "NE";
            }
            else if (angle &gt;= Math.PI / 2 &amp;&amp; angle &lt; Math.PI)
            {
